import{_ as d,C as n,o as e,c as l,j as i,E as r,a as s,a2 as o}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"n":2,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":4,"title":"Foydalanuvchi ssenariysi, User Flow va Customer Journey Map (CJM)","lead":"Dizayn chiroyli tugmalardan emas, balki foydalanuvchining ilova ichida adashmay, o'z maqsadiga erishishidan boshlanadi. Ushbu darsda foydalanuvchi hikoyasi (ssenariy) yozish, harakatlar xaritasi (User Flow) va hissiyotlar yo'li (CJM)ni loyihalashni o'rganamiz.","link":"/mentor/9-sinf/hafta-02/dars-1","slide":"/slaydlar/9-sinf/hafta-02/dars-1.html","test":"/slaydlar/9-sinf/hafta-02/dars-1-test.html"},{"g":5,"title":"Wireframe tushunchasi va Balsamiq dasturiga kirish","lead":"Uy qurishdan oldin uning chizmasi (cherteoj) chiziladi. Sayt va ilovalar yaratishda esa eng birinchi bo'lib Wireframe — interfeys skeleti loyihalanadi. Ushbu darsda nima uchun eng yaxshi dizaynlar oq-qora rangda boshlanishini va Balsamiq dasturida tezkor maketlar yasashni o'rganamiz.","link":"/mentor/9-sinf/hafta-02/dars-2","slide":"/slaydlar/9-sinf/hafta-02/dars-2.html","test":"/slaydlar/9-sinf/hafta-02/dars-2-test.html"},{"g":6,"title":"Balsamiq va Axure RP: asosiy UI komponentlar va dastlabki interfeys sxemalari","lead":"Birgina g'oya bor, lekin uni millionlab foydalanuvchilar tushunadigan interfeysga qanday aylantirish mumkin? Ushbu darsda professional Axure RP va Balsamiq vositalarida murakkab bloklar, sahifalar navigatsiyasi, kulranglar ierarxiyasi va wireframelarni Figmaga tayyorlashni o'rganamiz.","link":"/mentor/9-sinf/hafta-02/dars-3","slide":"/slaydlar/9-sinf/hafta-02/dars-3.html","test":"/slaydlar/9-sinf/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf/hafta-02/index.md","filePath":"mentor/9-sinf/hafta-02/index.md"}`),h={name:"mentor/9-sinf/hafta-02/index.md"},m={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},y={id:"baholash-mezoni",tabindex:"-1"};function f(b,a,q,c,k,v){const t=n("Icon");return e(),l("div",null,[i("div",m,[i("h2",u,[r(t,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Har bir vazifa 20–30 daqiqa. Natijalarni daftarda yoki bitta hujjatda (Google Docs, Notes, Balsamiq, Figma/Canva) saqlang; skrinshot va chizmalarni shu hujjatga qo&#39;shing. Topshirish: keyingi dars boshida mentorga ko&#39;rsating.</p><h2 id="_4-dars-uchun-ssenariy-user-flow-va-cjm" tabindex="-1">4-dars uchun (Ssenariy, User Flow va CJM) <a class="header-anchor" href="#_4-dars-uchun-ssenariy-user-flow-va-cjm" aria-label="Permalink to &quot;4-dars uchun (Ssenariy, User Flow va CJM)&quot;">​</a></h2><p><strong>1-topshiriq: «Mening ilovamdagi ssenariy va User Flow»</strong> (20–25 daqiqa)</p><ol><li>3-darsda tayyorlagan personangizni (yoki yangi personani) oling.</li><li>Uning ilovadagi bitta aniq vazifani (masalan: kitob yuklab olish yoki ovqat buyurtma qilish) bajarish ssenariysini 4 ta savol asosida yozing (Kim? Qayerda/qachon? Nima maqsad? Qanday harakatlar?).</li><li>Ushbu ssenariy bo&#39;yicha kamida 5 ta ekran va 1 ta qaror qabul qilish rombi (Ha/Yo&#39;q) qatnashgan User Flow blok-sxemasini chizing (daftarda yoki onlayn doskada).</li><li>Oqimda foydalanuvchi adashishi mumkin bo&#39;lgan 1 ta og&#39;riq nuqtasini belgilang va unga dizayn yechimini 1 jumlada taklif qiling.</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;liq yozilgan ssenariy matni, rombli User Flow chizmasi va bitta og&#39;riq nuqtasi yechimi. <strong>Nimani topshirasiz:</strong> daftardagi chizma rasmi yoki FigJam/Miro skrinshoti.</p><h2 id="_5-dars-uchun-wireframe-tushunchasi-va-balsamiq" tabindex="-1">5-dars uchun (Wireframe tushunchasi va Balsamiq) <a class="header-anchor" href="#_5-dars-uchun-wireframe-tushunchasi-va-balsamiq" aria-label="Permalink to &quot;5-dars uchun (Wireframe tushunchasi va Balsamiq)&quot;">​</a></h2><p><strong>2-topshiriq: «Low-fi qog&#39;oz eskizdan Balsamiqqa»</strong> (20–30 daqiqa)</p><ol><li>4-darsdagi User Flow&#39;ning asosiy 1 ta ekrani (masalan, Bosh sahifa yoki Mahsulot kartasi) uchun daftarga qalamda oddiy eskiz chizing.</li><li>Rasmlar o&#39;rniga &quot;X&quot; belgisi (Image placeholder) qo&#39;ying, tugma va sarlavhalarni joylang.</li><li>So&#39;ngra Balsamiq dasturida (balsamiq.cloud demo yoki desktop) xuddi shu ekranni raqamli wireframe qilib tering.</li><li>Quick Add orqali kamida 4 xil element (Button, Heading, Image, TextInput) qo&#39;shing.</li><li>Tayyor wireframeni PNG yoki PDF formatida eksport qiling.</li></ol><p><strong>Kutiladigan natija:</strong> daftardagi dastlabki eskiz va Balsamiqdan eksport qilingan raqamli wireframe tasviri. <strong>Nimani topshirasiz:</strong> qog&#39;oz eskiz fotosurati va Balsamiq PNG fayli.</p><h2 id="_6-dars-uchun-balsamiq-va-axure-rp-interfeys-sxemalari" tabindex="-1">6-dars uchun (Balsamiq va Axure RP interfeys sxemalari) <a class="header-anchor" href="#_6-dars-uchun-balsamiq-va-axure-rp-interfeys-sxemalari" aria-label="Permalink to &quot;6-dars uchun (Balsamiq va Axure RP interfeys sxemalari)&quot;">​</a></h2><p><strong>3-topshiriq: «Home_books to&#39;liq veb-wireframe&#39;i va Grayscale»</strong> (20–30 daqiqa)</p><ol><li>Axure RP (yoki Balsamiq/Figma)da veb-sahifa bosh ekrani wireframe&#39;ini yarating.</li><li>Sahifani <code>Home_books</code> deb nomlang.</li><li>Sahifaga Header (Logo, Menyu, Kirish tugmasi), Katta Banner, 3 ta kitob kartasi (Grid) va Footer bloklarini joylashtiring.</li><li>Kulranglar ierarxiyasini (Grayscale) to&#39;g&#39;ri qo&#39;llang: fon och kulrang, kartalar oq, asosiy sarlavha va tugmalar to&#39;q kulrang bo&#39;lsin.</li><li>Tayyor loyihani <code>home_books_wireframe.png</code> sifatida eksport qiling.</li></ol><p><strong>Kutiladigan natija:</strong> proporsiyalari toza, kulranglar ierarxiyasiga ega bo&#39;lgan to&#39;liq veb-sahifa wireframe&#39;i. <strong>Nimani topshirasiz:</strong> eksport qilingan PNG tasvir fayli.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Keyingi hafta boshida o&#39;quvchilarning User Flow&#39;larida &quot;tupik&quot; (chiqish yo&#39;li yo&#39;q) holatlar bor-yo&#39;qligini tekshiring. Wireframe&#39;larda rang ishlatilmaganligiga (faqat oq-qora va kulrang bo&#39;lishiga), rasmlar o&#39;rniga to&#39;g&#39;ri &quot;X&quot; placeholderlari qo&#39;yilganligiga hamda elementlar orasidagi masofalar (white space) bir xilligiga e&#39;tibor qarating.</p>',15))]),i("div",g,[i("h2",y,[r(t,{name:"list-checks"}),a[3]||(a[3]=s(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Shkala haqida.</strong> 100 ballik shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>. Guruhdagi o&#39;quvchilar soni belgilanmagan, shuning uchun 3 ta bo&#39;sh qatorli shablon berilgan (mentor o&#39;zgartirishi mumkin).</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mavzu mohiyatini tushunadi va aytib bera oladi (tezkor nazorat)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri, mantiqiy va to&#39;liq bajarilgan</td><td>30</td></tr><tr><td>Dizayn mantig&#39;i: User Flow to&#39;g&#39;ri shoxlangan, wireframe ierarxiyasi toza</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><h2 id="_4-dars-ssenariy-user-flow-va-cjm" tabindex="-1">4-dars (Ssenariy, User Flow va CJM) <a class="header-anchor" href="#_4-dars-ssenariy-user-flow-va-cjm" aria-label="Permalink to &quot;4-dars (Ssenariy, User Flow va CJM)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: ssenariyning 4 ta savolga javob berishi; User Flow da romb (shartli tanlov) mavjudligi; og&#39;riq nuqtasi va hissiyotlar.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dizayn mantig&#39;i /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="_5-dars-wireframe-va-balsamiq" tabindex="-1">5-dars (Wireframe va Balsamiq) <a class="header-anchor" href="#_5-dars-wireframe-va-balsamiq" aria-label="Permalink to &quot;5-dars (Wireframe va Balsamiq)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: Low-fidelity qoidalariga rioya qilingani (rangsiz, X placeholderlar); Balsamiq vositalarini to&#39;g&#39;ri qo&#39;llash.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dizayn mantig&#39;i /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="_6-dars-axure-rp-va-grayscale-ierarxiyasi" tabindex="-1">6-dars (Axure RP va Grayscale ierarxiyasi) <a class="header-anchor" href="#_6-dars-axure-rp-va-grayscale-ierarxiyasi" aria-label="Permalink to &quot;6-dars (Axure RP va Grayscale ierarxiyasi)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: sahifalarni to&#39;g&#39;ri nomlash (<code>Home_books</code>), kulrang tuslar (Grayscale) bilan muhimlikni ko&#39;rsatish, PNG eksport.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dizayn mantig&#39;i /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="hafta-yakuni" tabindex="-1">Hafta yakuni <a class="header-anchor" href="#hafta-yakuni" aria-label="Permalink to &quot;Hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>4-dars</th><th>5-dars</th><th>6-dars</th><th>O&#39;rtacha</th><th>Baho</th><th>Izoh (kuchli/zaif tomonlari)</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="hafta-xulosasi-va-keyingi-haftaga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi haftaga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-haftaga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi haftaga ko&#39;prik&quot;">​</a></h2><p><strong>Bu hafta:</strong> foydalanuvchi ssenariysi (User Scenario), User Flow oqim xaritasi, Customer Journey Map (CJM); Wireframe tushunchasi (Low-fi vs High-fi), Balsamiq dasturining qalamaki falsafasi va Quick Add; Axure RP panellari, kulranglar ierarxiyasi (Grayscale) va Figmaga tayyorlash.</p><p><strong>Keyingi hafta (3-hafta, 7–9 darslar):</strong> Wireframe yasash amaliyotini davom ettiramiz va chuqurlashtiramiz; turli xil qurilmalar (planshet, desktop, mobil) uchun moslashuvchan maketlar va murakkab interfeys bloklarini loyihalaymiz.</p>',17))])])}const x=d(h,[["render",f]]);export{z as __pageData,x as default};
